// biome-ignore format: compact hook for deterministic backfill, keep <10 lines for PR budget
/// <reference path="../pb_data/types.d.ts" />
function backfillOrigin(app){let p=0;const n=200;let r=false;while(true){let s;try{s=app.findRecordsByFilter("services","originLocationId = '' || originLocationId = null","+id",n,p*n)}catch(_){return false}r=true;if(!s||!s.length)break;for(const v of s){const id=v.get("id"),cur=v.get("locationId");let o=null;try{const c=app.findRecordsByFilter("service_events","ServiceId = {:sid} && kind = 'created'","+changedAt",1,0,{sid:id});if(c&&c.length)o=c[0].get("fromLocationId")||c[0].get("toLocationId")||null}catch(_){}if(!o){let h=false;try{const t=app.findRecordsByFilter("service_events","ServiceId = {:sid} && kind = 'location_changed'","id",1,0,{sid:id});h=!!(t&&t.length)}catch(_){}if(!h)o=cur;else{console.log(`[backfill] ambiguous ${id}`);continue}}if(!o)continue;v.set("originLocationId",o);try{app.save(v)}catch(e){console.log(`[backfill] ${id}:${e}`)}}if(s.length<n)break;p++}return r}onBootstrap((e)=>{e.next();let d=false;try{d=backfillOrigin($app)}catch(err){console.log("[backfill] bootstrap",err)}if(d)try{cronRemove("backfill-origin")}catch(_){}try{cronAdd("backfill-origin","*/5 * * * *",()=>{function backfillOrigin2(app){let p=0;const n=200;let r=false;while(true){let s;try{s=app.findRecordsByFilter("services","originLocationId = '' || originLocationId = null","+id",n,p*n)}catch(_){return false}r=true;if(!s||!s.length)break;for(const v of s){const id=v.get("id"),cur=v.get("locationId");let o=null;try{const c=app.findRecordsByFilter("service_events","ServiceId = {:sid} && kind = 'created'","+changedAt",1,0,{sid:id});if(c&&c.length)o=c[0].get("fromLocationId")||c[0].get("toLocationId")||null}catch(_){}if(!o){let h=false;try{const t=app.findRecordsByFilter("service_events","ServiceId = {:sid} && kind = 'location_changed'","id",1,0,{sid:id});h=!!(t&&t.length)}catch(_){}if(!h)o=cur;else{console.log(`[backfill] ambiguous ${id}`);continue}}if(!o)continue;v.set("originLocationId",o);try{app.save(v)}catch(e){console.log(`[backfill] ${id}:${e}`)}}if(s.length<n)break;p++}return r}let ran=false;try{ran=backfillOrigin2($app)}catch(err){console.log("[backfill] cron",err);return}if(ran)try{cronRemove("backfill-origin")}catch(_){}})}catch(err){console.log("[backfill] cron reg",err)}});
